CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role VARCHAR(30) NOT NULL,graduated BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(20) NOT NULL); CREATE TABLE IF NOT EXISTS volunteer_profiles(user_id UUID PRIMARY KEY,document VARCHAR(20) NOT NULL UNIQUE,phone VARCHAR(30),address VARCHAR(200),availability VARCHAR(200),training_level VARCHAR(30) NOT NULL);
